import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Type Alias: AreaTrigger","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/type-aliases/AreaTrigger.md","filePath":"api/twine/type-aliases/AreaTrigger.md"}'),c={name:"api/twine/type-aliases/AreaTrigger.md"};function i(s,e,n,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<p><a href="./../">twine</a> / AreaTrigger</p><h1 id="type-alias-areatrigger" tabindex="-1">Type Alias: AreaTrigger <a class="header-anchor" href="#type-alias-areatrigger" aria-label="Permalink to &quot;Type Alias: AreaTrigger&quot;">​</a></h1><blockquote><p><strong>AreaTrigger</strong> = { <code>center</code>: <a href="./Vec3.html"><code>Vec3</code></a>; <code>kind</code>: <code>&quot;region&quot;</code>; <code>radius</code>: <code>number</code>; } | { <code>from</code>: <a href="./Vec3.html"><code>Vec3</code></a>; <code>kind</code>: <code>&quot;cuboid&quot;</code>; <code>to</code>: <a href="./Vec3.html"><code>Vec3</code></a>; } | { <code>kind</code>: <code>&quot;zones&quot;</code>; <code>zones</code>: <a href="./Zone.html"><code>Zone</code></a>[]; } | <a href="./../interfaces/PlayersTrigger.html"><code>PlayersTrigger</code></a> | <a href="./../interfaces/ScoreTrigger.html"><code>ScoreTrigger</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/area.ts#L49" target="_blank" rel="noreferrer">area.ts:49</a></p><p>Declares how an <code>area</code> switches itself on. The factory emits a cheap per-tick detector for the area; presence triggers (<code>region</code>/<code>cuboid</code>/<code>zones</code>) are tracked both ways - the area turns on while a player is inside and off once the region empties - while <code>score</code> latches on until something calls <code>deactivate</code>.</p><ul><li><code>region</code> - a single sphere: shorthand for one <code>sphere</code> <a href="./Zone.html">Zone</a>.</li><li><code>cuboid</code> - a single axis-aligned box between two corners.</li><li><code>zones</code> - a <strong>union</strong> of any number of spheres/boxes; a player anywhere inside the union counts. Use this to fence off an irregular area out of several boxes, or to cover several rooms with one flag.</li><li><code>score</code> - activate while <code>#&lt;target&gt; &lt;objective&gt;</code> matches a value (<code>equals</code>) or a band of values (<code>matches</code>), driving areas from your own scoreboard state rather than from geometry. Two areas can share coordinates and still be mutually exclusive, because what separates them is the score, not space.</li><li><code>players</code> - activate while <strong>any</strong> player matches a Selector. The membership form of a presence trigger: where <code>zones</code> asks &quot;is anyone in this space&quot;, this asks &quot;is anyone in this <em>set</em>&quot; - tagged, scored, holding something, in a given gamemode. Use it when what defines the area is a condition the pack maintains per player rather than the player&#39;s position.</li></ul><p>Areas with no trigger are activated manually (<code>/function &lt;ns&gt;:&lt;name&gt;/activate</code>) or by another module.</p>',7)])])}const f=o(c,[["render",i]]);export{p as __pageData,f as default};
